     "summary": "自从去年我妈被电信诈骗之后，又卷入保健品诈骗，购买了不少高价保健品，今年8月中旬，我查看我妈的银行卡账单时，忽然发现有一笔1480元的交易记录，我赶忙询问我妈，是不是又买了什么保健品，结果却出乎我的意料，这笔钱用来报了一门配音课程。我感觉，一年下来，我仿佛成了家里免费的&ldquo;反诈宣传员&rdquo;，让我感到非常无奈。 一、被骗的整个过程 整件事始于一套针对性极强、迷惑性很高的营销套路。 原来，有一家专门面向老年人推广的配音培训公司，在微信群里向老年人大肆宣传参与朗诵",
